  "chunks": [
    {
      "chunk_type": "isnad",
      "arabic_text": "اَلْحُسَيْنُ بْنُ سَعِيدٍ عَنْ حَمَّادِ بْنِ عِيسَى قَالَ سَمِعْتُ أَبَا عَبْدِ ٱللَّهِ عَلَيْهِ ٱلسَّلَامُ يَقُولُ",
      "translations": {
        "en": "Al-Husayn ibn Sa'id from Hammad ibn Isa said: I heard Abu Abdillah (peace be upon him) saying:"
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "«حَدَّثَنِي أَبِي: «أَنَّ رَسُولَ ٱللَّهِ صَلَّى ٱللَّهُ عَلَيْهِ وَ آلِهِ قَضَى بِشَاهِدٍ وَ يَمِينٍ»»",
      "translations": {
        "en": "He told me: 'The Messenger of Allah (peace be upon him and his family) ruled based on a witness and an oath.'"
      }
    }
  ],
  "translations": {
    "en": {
      "summary": "This hadith establishes a fundamental principle of Islamic judicial procedure, stating that the Prophet Muhammad (peace be upon him) issued rulings based on the combination of a witness (testimony) and an oath (sworn statement by the defendant or plaintiff). It highlights the evidentiary standards used in early Islamic courts.",
      "seo_question": "What is the basis of judicial ruling in Islam according to the Prophet?",
      "key_terms": {
        "قَضَى": "He ruled / He judged",
        "بِشَاهِدٍ": "With a witness (testimony)",
        "وَيَمِينٍ": "And an oath",
        "ر (sworn statement)"
